update pms_template
   set tmpl_nm = #{f.tmplNm}, proj_type = #{f.projType}, anchor = #{f.anchor}, use_yn = #{f.useYn}, remark = #{f.remark},
       row_ver = row_ver + 1, updated_at = now(), updated_by = #{by}
 where tmpl_id = #{id} and row_ver = #{f.rowVer}

update pms_template_task
   set task_type = #{f.taskType}, task_nm = #{f.taskNm}, offset_days = #{f.offsetDays}, duration_days = #{f.durationDays},
       std_hours = #{f.stdHours}, remark = #{f.remark}, row_ver = row_ver + 1, updated_at = now(), updated_by = #{by}
 where tt_id = #{id} and row_ver = #{rowVer}

update pms_template_task
   set parent_id = #{parentId}, seq = #{seq}, row_ver = row_ver + 1, updated_at = now(), updated_by = #{by}
 where tt_id = #{id}

