update pms_project
   set proj_nm = #{f.projNm}, proj_type = #{f.projType}, cust_id = #{f.custId}, plant_cd = #{f.plantCd},
       pm_user_id = #{f.pmUserId}, sop_date = #{f.sopDate}, remark = #{f.remark},
       row_ver = row_ver + 1, updated_at = now(), updated_by = #{by}
 where proj_id = #{id} and row_ver = #{rowVer}

update pms_project
   set status = #{status}, status_reason = #{reason}, closed_on = #{closedOn},
       row_ver = row_ver + 1, updated_at = now(), updated_by = #{by}
 where proj_id = #{id} and row_ver = #{rowVer}

update pms_project set apr_to = null, apr_id = null, status = #{status}, closed_on = #{closedOn},
       row_ver = row_ver + 1, updated_at = now(), updated_by = #{by}
 where proj_id = #{id} and apr_to is not null

update pms_project set plan_start = #{planStart}, plan_end = #{planEnd}, progress_pct = #{progressPct}
 where proj_id = #{id}
   and (plan_start is distinct from #{planStart} or plan_end is distinct from #{planEnd} or progress_pct <> #{progressPct})

update pms_task
   set task_type = #{f.taskType}, task_nm = #{f.taskNm}, owner_user_id = #{f.ownerUserId},
       plan_start = #{f.planStart}, plan_end = #{f.planEnd}, act_start = #{f.actStart}, act_end = #{f.actEnd},
       progress_pct = #{f.progressPct}, status = #{f.status}, remark = #{f.remark}, plan_hours = #{f.planHours},
       row_ver = row_ver + 1, updated_at = now(), updated_by = #{by}
 where task_id = #{id} and row_ver = #{rowVer}

update pms_task
   set parent_id = #{parentId}, seq = #{seq}, row_ver = row_ver + 1, updated_at = now(), updated_by = #{by}
 where task_id = #{id}

update pms_task
   set is_summary = #{t.isSummary}, plan_start = #{t.planStart}, plan_end = #{t.planEnd}, act_start = #{t.actStart},
       act_end = #{t.actEnd}, progress_pct = #{t.progressPct}, status = #{t.status}, plan_hours = #{t.planHours},
       row_ver = row_ver + 1, updated_at = now(), updated_by = #{by}
 where task_id = #{t.taskId}
